function normalizar(t) {
  try {
    return (t || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
  } catch {
    return (t || "").toLowerCase()
  }
}
function W() {
  const t = new Date(),
    o = t.getTimezoneOffset()
  return new Date(t.getTime() - o * 6e4).toISOString().slice(0, 16)
}
function textoParaHtml(t) {
  return t
    .split(/\n\n+/)
    .map((par) => `<p>${par.replace(/\n/g, "<br>")}</p>`)
    .join("")
}
function limparHtml(t) {
  const d = document.createElement("div")
  d.innerHTML = t
  d.querySelectorAll("script,style,iframe,object,embed,link,meta,form,input,button,textarea,select").forEach((n) => n.remove())
  d.querySelectorAll("*").forEach((n) => {
    for (const a of [...n.attributes]) {
      const nome = a.name.toLowerCase()
      if (nome.startsWith("on") || ["style", "class", "id", "name", "srcset", "formaction"].includes(nome)) n.removeAttribute(a.name)
    }
  })
  return d.innerHTML
}

